CREATE TABLE IF NOT EXISTS public.production_digital_instructions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,instruction_code VARCHAR(80) NOT NULL,title TEXT NOT NULL,work_station_id UUID,version_no INTEGER NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',content JSONB NOT NULL DEFAULT '{}'::jsonb,first_piece_required BOOLEAN NOT NULL DEFAULT FALSE,evidence_reference TEXT,created_by UUID,approved_by UUID,approved_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,instruction_code,version_no));
CREATE TABLE IF NOT EXISTS public.production_mes_executions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,job_order_id UUID,work_station_id UUID NOT NULL,instruction_id UUID,operator_id UUID,event_type VARCHAR(24) NOT NULL CHECK(event_type IN('START','PAUSE','RESUME','COMPLETE','MATERIAL_SCAN','QC_HOLD','FIRST_PIECE_APPROVED')),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),barcode VARCHAR(160),quantity NUMERIC(18,3),reason_code VARCHAR(80),evidence JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.production_autonomy_exceptions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,source_type VARCHAR(40) NOT NULL,source_id UUID,work_station_id UUID,severity VARCHAR(12) NOT NULL,exception_type VARCHAR(60) NOT NULL,recommendation TEXT NOT NULL,recommended_action VARCHAR(40) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS public.production_energy_tariffs(tenant_id UUID NOT NULL,work_station_id UUID NOT NULL,cost_per_kwh NUMERIC(12,4) NOT NULL,carbon_kg_per_kwh NUMERIC(12,6) NOT NULL DEFAULT 0.4,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(tenant_id,work_station_id));
CREATE INDEX IF NOT EXISTS idx_mes_exec ON public.production_mes_executions(tenant_id,work_station_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_autonomy_open ON public.production_autonomy_exceptions(tenant_id,status,severity);
CREATE UNIQUE INDEX IF NOT EXISTS uq_autonomy_source ON public.production_autonomy_exceptions(tenant_id,source_type,source_id);
CREATE TABLE IF NOT EXISTS public.production_station_asset_maps(tenant_id UUID NOT NULL,work_station_id UUID NOT NULL,asset_id UUID NOT NULL,PRIMARY KEY(tenant_id,work_station_id));
CREATE TABLE IF NOT EXISTS public.production_vision_inspections(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,work_station_id UUID NOT NULL,job_order_id UUID,source_image_reference TEXT NOT NULL,inspection_type VARCHAR(40) NOT NULL,verdict VARCHAR(20) NOT NULL CHECK(verdict IN('PASS','FAIL','REVIEW')),confidence_pct NUMERIC(5,2) NOT NULL,evidence JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.production_aps_recommendations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL,job_order_id UUID,work_station_id UUID,priority_score NUMERIC(12,3) NOT NULL,recommendation TEXT NOT NULL,reasoning JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(20) NOT NULL DEFAULT 'PROPOSED',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
